fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x000010);
    let mut i: i32 = 0;
    while i < 48 {
        let speed: i32 = hash(i * 7 + 1) % 4 + 3;
        let len: i32 = speed * 3;
        let x: i32 = (hash(i * 13 + 5) + t / 4) % w;
        let y: i32 = (hash(i * 11 + 3) + t * speed) % (h + len);
        host::display::draw_line(x, y - len, x - 2, y, 0x4060c0);
        i = i + 1;
    }
    host::display::present();
}
